<?php declare(strict_types=1);require_once __DIR__.'/includes/store.php';$pageTitle='Contact us';$sent=false;$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_is_valid($_POST['csrf_token']??null)){http_response_code(419);exit('Invalid form token.');}$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$message=trim((string)($_POST['message']??''));if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$message==='')$errors[]='Complete your name, valid email and message.';else{$sent=true;}}require __DIR__.'/includes/header.php';?><section class="container py-5"><h1 class="h2">Contact BlueCircuit Electronics</h1><p class="text-secondary">Questions about products, delivery or an order? Get in touch.</p><div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm p-4"><?php if($sent):?><div class="alert alert-success">Your message has been validated in this demo. Connect an email service or contact-message table to store and deliver messages.</div><?php else:?><?php foreach($errors as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-label">Name</label><input class="form-control mb-3" name="name" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Message</label><textarea class="form-control mb-3" name="message" rows="5" required></textarea><button class="btn btn-primary">Send message</button></form><?php endif;?></div></div><div class="col-lg-5"><div class="card border-0 shadow-sm p-4 mb-3"><h2 class="h5">Business information</h2><p><strong>Location</strong><br><?=nl2br(e(setting('business_location','Add your shop location in Admin → Store settings.')))?></p><p><strong>Working hours</strong><br><?=nl2br(e(setting('working_hours','Monday–Saturday, 9:00 AM–6:00 PM')))?></p><p class="mb-0"><strong>WhatsApp</strong><br><?=e(setting('whatsapp_number','Add a WhatsApp number in Store settings.'))?></p></div><div class="card border-0 shadow-sm p-4"><h2 class="h5">Find our business</h2><p class="text-secondary mb-0">Once a public address is configured, you can add a verified map embed here. No location is fabricated in this starter.</p></div></div></div></section><?php require __DIR__.'/includes/footer.php';?>
